333	export function buildProductionStockMovementRows(receiptRows, issueRows) {
334	  const grouped = new Map();
335	
336	  const touchRow = (key, seed) => {
337	    if (!grouped.has(key)) {
338	      grouped.set(key, {
339	        issueDate: seed.issueDate,
340	        lotNo: seed.lotNo,
341	        productCode: seed.productCode,
342	        productName: seed.productName,
343	        inboundQuantity: 0,
