345	        issueQuantity: 0,
346	        issueWeightKg: 0,
347	        returnQuantity: 0,
348	        returnWeightKg: 0,
349	        wasteQuantity: 0,
350	        wasteWeightKg: 0,
351	      });
352	    }
353	
354	    return grouped.get(key);
355	  };
356	
357	  (Array.isArray(receiptRows) ? receiptRows : []).forEach((row) => {
358	    const issueDate = normalizeText(row?.groupDate);
359	    const lotNo = normalizeText(row?.lotNo) || "-";
360	    const productCode = normalizeUpperText(row?.productCode) || "-";
361	    const productName = normalizeText(row?.productName) || "-";
362	    const key = [issueDate, lotNo, productCode].join("|");
363	    const groupedRow = touchRow(key, {
364	      issueDate,
365	      lotNo,
366	      productCode,
367	      productName,
368	    });
369	
370	    groupedRow.inboundQuantity = roundDecimal(groupedRow.inboundQuantity + normalizeDecimal(row?.quantity));
371	    groupedRow.inboundWeightKg = roundDecimal(groupedRow.inboundWeightKg + normalizeDecimal(row?.totalNetWeightKg));
372	  });
373	
374	  (Array.isArray(issueRows) ? issueRows : []).forEach((row) => {
375	    const issueDate = normalizeText(row?.issueDate);
376	    const lotNo = normalizeText(row?.lotNo) || "-";
377	    const productCode = normalizeUpperText(row?.productCode) || "-";
378	    const productName = normalizeText(row?.productName) || "-";
379	    const key = [issueDate, lotNo, productCode].join("|");
380	    const groupedRow = touchRow(key, {
381	      issueDate,
382	      lotNo,
383	      productCode,
384	      productName,
385	    });
386	
387	    groupedRow.issueQuantity = roundDecimal(groupedRow.issueQuantity + normalizeDecimal(row?.quantity));
388	    groupedRow.issueWeightKg = roundDecimal(groupedRow.issueWeightKg + normalizeDecimal(row?.totalWeightKg));
389	  });
390	
391	  return recalculateProductionStockMovementBalances(Array.from(grouped.values()));
392	}

