      fgByWip.get(row.materialSkuCode).add(row.rootSkuCode);
    });

    const wipSkus = Array.from(fgByWip.keys());
    if (!wipSkus.length) return { data: [], meta: { fgCount: fgSkus.length } };

    // 4. Product names/units
    const { data: wipProducts, error: wipError } = await db
      .from("products_cache")
      .select("sku_code,sku_name,uom_name")
      .in("sku_code", wipSkus);
    if (wipError) throw wipError;

